import numpy as np
def rots(g):
    a=np.array(g); outs={}
    for k_,f in [('id',lambda x:x),('r90',np.rot90(a,1)),('r180',np.rot90(a,2)),('r270',np.rot90(a,3))]:
        outs[k_]=f.tolist()
    # flips
    for name,f in [('fliph',np.fliplr(a)),('flipv',a[::-1]),('transp',a.T)]:
        outs[name]=f.tolist()
    return outs
